/**
 * The one StyleX compile step, shared by the production bundle
 * (frontend-build.ts), the OPENSESSION_DEV=1 HMR server
 * (stylex-dev-plugin.ts, wired in bunfig.toml) and unit tests
 * (scripts/test-setup.ts). StyleX has no runtime: `stylex.create` throws
 * unless this Babel pass has rewritten it, so all three have to run it, and
 * they must agree on options or a class name hashed in one would not match the
 * CSS generated by another.
 *
 * Babel and the StyleX plugin are build-only dependencies, loaded on first use:
 * a release box installs with --production and never compiles the frontend.
 */
import type { BunPlugin } from "bun";
import { join, resolve } from "path";

export const STYLEX_REPO_ROOT = resolve(import.meta.dir, "../../../../..");
export const STYLEX_FRONTEND_SRC = join(
  STYLEX_REPO_ROOT,
  "packages/core/opensession-server/src/frontend",
);

/** One rule as the Babel plugin reports it in `metadata.stylex`. */
export type StylexRule = [string, { ltr: string; rtl?: string | null }, number];

/** Cheap pre-filter: only files that import StyleX pay for a Babel pass. */
export function usesStylex(path: string, source: string): boolean {
  return (
    path.startsWith(STYLEX_FRONTEND_SRC) && source.includes("@stylexjs/stylex")
  );
}

/** The slice of @babel/core this module calls (Babel 7 ships no types). */
type Babel = {
  transformAsync(
    code: string,
    options: Record<string, unknown>,
  ): Promise<{ code?: string | null; metadata?: unknown } | null>;
};
type StylexPlugin = typeof import("@stylexjs/babel-plugin").default;
let loaded: Promise<{
  babel: Babel;
  stylex: StylexPlugin;
  syntaxTs: unknown;
}> | null = null;

// Specifiers held in variables so a `bun build --compile` server binary does
// not try to bundle the compiler toolchain it never runs.
const BABEL_CORE = "@babel/core";
const BABEL_SYNTAX_TS = "@babel/plugin-syntax-typescript";
const STYLEX_BABEL = "@stylexjs/babel-plugin";

function load() {
  return (loaded ??= Promise.all([
    import(BABEL_CORE),
    import(STYLEX_BABEL),
    import(BABEL_SYNTAX_TS),
  ]).then(([babel, stylex, syntaxTs]) => ({
    babel: interop(babel) as Babel,
    stylex: interop(stylex) as StylexPlugin,
    syntaxTs: interop(syntaxTs),
  })));
}

/** CommonJS packages arrive as `{ default: module.exports }`, and Babel's own
 *  ESM-compiled ones nest a second `default` inside that. */
function interop(mod: unknown): unknown {
  let m = mod as { default?: unknown; __esModule?: boolean };
  while (m && typeof m === "object" && "default" in m && m.default) {
    if (typeof m === "object" && "transformAsync" in m) break;
    m = m.default as typeof m;
  }
  return m;
}

export type StylexMode = "build" | "dev" | "test";

/**
 * Compile one source file's `stylex.create` / `stylex.props` calls. Returns
 * the rewritten TS/TSX (types and JSX left for the next transform) and the CSS
 * rules it contributed.
 */
export async function transformStylex(
  path: string,
  source: string,
  mode: StylexMode,
): Promise<{ code: string; rules: StylexRule[] }> {
  const { babel, stylex, syntaxTs } = await load();
  const result = await babel.transformAsync(source, {
    filename: path,
    babelrc: false,
    configFile: false,
    sourceMaps: false,
    // Keep the source shape: oxc (React Compiler) or Bun parses the output.
    retainLines: mode !== "build",
    plugins: [
      [syntaxTs, { isTSX: path.endsWith(".tsx") }],
      [
        stylex,
        {
          dev: mode === "dev",
          test: mode === "test",
          // CSS is collected and linked, never injected at runtime: a
          // runtime <style> lands at the top of <head>, ahead of base.css,
          // and carries StyleX's own specificity bumps, so dev would cascade
          // differently from production.
          runtimeInjection: false,
          treeshakeCompensation: true,
          importSources: ["@stylexjs/stylex"],
          unstable_moduleResolution: {
            type: "commonJS",
            rootDir: STYLEX_REPO_ROOT,
          },
        },
      ],
    ],
  });
  if (!result?.code) throw new Error(`StyleX produced no output for ${path}`);
  const rules =
    ((result.metadata as { stylex?: StylexRule[] } | undefined)?.stylex as
      | StylexRule[]
      | undefined) ?? [];
  return { code: result.code, rules };
}

/**
 * Turn every collected rule into one stylesheet.
 *
 * While Tailwind and StyleX coexist, this sheet is linked AFTER base.css and
 * BEFORE the Tailwind utilities, all unlayered, so the cascade is the one the
 * app already has: a primitive's StyleX class (0,1,0) beats base.css's element
 * resets, and a caller's Tailwind class of equal specificity wins on source
 * order, the way tailwind-merge let a caller's `className` win before.
 *
 * `legacyDisableLayers` drops StyleX's `:not(#\#)` specificity ladder for plain
 * source order (rules are emitted sorted by priority). StyleX still doubles
 * the class inside an at-rule (`.x.x:hover`) so a media value beats a pseudo
 * one; that would also beat a caller's `hover:` utility, so the doubling is
 * undone here. Once Tailwind is gone, switch to `useLayers: true` and delete
 * both workarounds.
 */
export async function stylexCss(rules: Iterable<StylexRule>): Promise<string> {
  const { stylex } = await load();
  const all = [...rules];
  if (all.length === 0) return "";
  const css = stylex.processStylexRules(all as never, {
    useLayers: false,
    legacyDisableLayers: true,
  });
  return css.replace(/\.([A-Za-z0-9_-]+)\.\1(?=[\s:{.,[)])/g, ".$1");
}

/**
 * A Bun.build plugin that compiles StyleX in "build" mode, for a side bundle
 * (a test fixture, a harness) whose class names must match the CSS that
 * compileAssets() emitted for the same sources.
 */
export function stylexBuildPlugin(): BunPlugin {
  return {
    name: "opensession-stylex-build",
    setup(build) {
      build.onLoad({ filter: /\.[jt]sx?$/ }, async (args) => {
        const source = await Bun.file(args.path).text();
        if (!usesStylex(args.path, source)) return undefined;
        const { code } = await transformStylex(args.path, source, "build");
        return {
          contents: code,
          loader: args.path.endsWith(".tsx") ? "tsx" : "ts",
        };
      });
    },
  };
}
